// The food dictionary, shared by Ricette and Everyday (copied unchanged in both apps).
// One line per food: id | department | it | de | en | other names (;) | kcal | protein | weights | of | basic
//   kcal / protein per 100 g; weights: piece, dens (g per ml), pack, can, slice, bunch in grams;
//   of = a more specific kind of that food (farina 00 → flour); basic = counts as always at home.
// Ids never change. A food merged into another stays as "old-id|>new-id".
// Generated by Ricette from tools/foods/*.txt; edit those, not this file. Imports nothing.

const DATA = `
/*DATA*/
`;

/* ---------- names ---------- */

export const simple = (s) => String(s || '').toLowerCase().replace(/ß/g, 'ss').normalize('NFD').replace(/\p{M}/gu, '')
  .replace(/\(.*?\)/g, ' ').replace(/['’`-]/g, ' ').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

// last-word forms: plurals in it/de/en (uova/uovo, pomodori/pomodoro, Zwiebeln/Zwiebel, eggs/egg)
const lastForms = (w) => [...new Set([w, w.replace(/(?:es|en|s|e|i|n)$/, ''), w.replace(/i$/, 'o'), w.replace(/e$/, 'a'), w.replace(/i$/, 'e'), w.replace(/a$/, 'e'), w.replace(/o$/, 'i')])];
const WEIGHT_KEYS = ['piece', 'dens', 'pack', 'can', 'slice', 'bunch'];
export const NONFOOD_DEPTS = ['household', 'care', 'baby'];

/* ---------- the table ---------- */

const FOOD = new Map(); // id → record
const GONE = new Map(); // old id → new id
const BUILTIN = [];
for (const line of DATA.trim().split('\n')) {
  const f = line.split('|');
  if (f[1] && f[1].startsWith('>')) { GONE.set(f[0], f[1].slice(1)); continue; }
  const [id, dept, it, de, en, alt = '', kcal = '', prot = '', weights = '', of = '', basic = ''] = f;
  const rec = { id, dept, it, de, en, alt: alt ? alt.split(';') : [] };
  if (kcal !== '') { rec.kcal = Number(kcal); rec.prot = Number(prot); }
  for (const kv of weights ? weights.split(' ') : []) { const [k, v] = kv.split('='); if (WEIGHT_KEYS.includes(k)) rec[k] = Number(v); }
  if (of) rec.of = of;
  if (basic) rec.basic = true;
  FOOD.set(id, rec);
  BUILTIN.push(rec);
}
/** Every built-in food record (read-only). */
export const FOODS = BUILTIN;

let INDEX = new Map(); // simplified name → id
let KEYS = [];         // [{ k, words, id, nonfood }] longest first
const memo = new Map();

function addNames(id, names) {
  for (const n of names) {
    const k = simple(n);
    if (k && !INDEX.has(k)) INDEX.set(k, id);
  }
}
function rebuild(userFoods = []) {
  INDEX = new Map();
  // the user's own names first: they win over built-in ones
  for (const u of userFoods) addNames(u.id, [u.it, u.de, u.en, ...(u.alt || [])].filter(Boolean));
  for (const r of BUILTIN) addNames(r.id, [r.it, r.de, r.en, ...r.alt]);
  KEYS = [...INDEX].map(([k, id]) => ({ k, words: k.split(' '), id, nonfood: NONFOOD_DEPTS.includes(food(id)?.dept) }))
    .filter((e) => e.k.length >= 3)
    .sort((a, b) => b.k.length - a.k.length);
  memo.clear();
}

/* ---------- lookups ---------- */

/** The record for an id (following ids of merged foods), or null. */
export function food(id) {
  let k = id;
  for (let i = 0; i < 5 && GONE.has(k); i++) k = GONE.get(k);
  return FOOD.get(k) || null;
}

/** A food's name in it / de / en. */
export function foodName(id, lang) {
  const r = food(id);
  if (!r) return '';
  return r[lang] || r.it || r.en || r.de || '';
}

// Does the keyword word `kw` match the name's word `w`? Plurals (a short ending) and
// German compounds (the keyword at the end of a longer word: "rinderhackfleisch").
function wordMatch(w, kw) {
  if (w === kw) return true;
  if (w.startsWith(kw) && w.length - kw.length <= (kw.length >= 4 ? 3 : 1)) return true;
  // Italian plurals: cavolo / cavoli, zucchina / zucchine
  if (kw.length >= 4 && w.length === kw.length && /[aeio]$/.test(w) && /[aeio]$/.test(kw) && w.slice(0, -1) === kw.slice(0, -1)) return true;
  if (kw.length >= 4 && w.length > kw.length) {
    const at = w.lastIndexOf(kw);
    if (at > 0 && w.length - (at + kw.length) <= 2) return true;
    if (kw.length >= 7 && w.startsWith(kw)) return true;
  }
  return false;
}
function matchAt(words, i, e) {
  for (let j = 0; j < e.words.length; j++) {
    const w = words[i + j];
    if (w == null) return false;
    const kw = e.words[j];
    const last = j === e.words.length - 1;
    if (last ? !wordMatch(w, kw) : !(w === kw || (w.startsWith(kw) && w.length - kw.length <= 2))) return false;
  }
  return true;
}

/**
 * Which food a name is: an id, or null.
 * Exact name, then plural forms of the last word, then the longest known name inside it
 * ("2 large eggs, beaten" → egg). Inside a longer name, household and personal-care words
 * win over food words ("sapone al limone" is soap, not lemons).
 */
export function foodOf(name) {
  const s = simple(name);
  if (!s) return null;
  if (memo.has(s)) return memo.get(s);
  let out = INDEX.get(s) || null;
  if (!out) {
    const ws = s.split(' ');
    for (const v of lastForms(ws[ws.length - 1])) {
      const id = INDEX.get([...ws.slice(0, -1), v].join(' '));
      if (id) { out = id; break; }
    }
  }
  if (!out) {
    const words = s.split(' ');
    let best = null; let bestNon = null;
    for (const e of KEYS) {
      if (bestNon) break;
      if (!e.nonfood && best && e.k.length < best.e.k.length) continue;
      for (let i = 0; i < words.length; i++) {
        if (!matchAt(words, i, e)) continue;
        if (e.nonfood) bestNon = { e, i };
        else if (!best || i < best.i) best = { e, i };
        break;
      }
    }
    out = (bestNon || best)?.e.id || null;
  }
  if (memo.size > 5000) memo.clear();
  memo.set(s, out);
  return out;
}

/**
 * An item's food: its stored `food` when known, else from its name.
 * `foodPinned: true` with no `food` = a person said it's none of the dictionary's foods.
 */
export function foodOfItem(x) {
  if (!x) return null;
  if (typeof x === 'string') return foodOf(x);
  if (x.food && food(x.food)) return food(x.food).id;
  if (x.foodPinned && !x.food) return null;
  return foodOf(x.name || x.raw || '');
}

const stem = (w) => (w.length >= 4 ? w.replace(/(?:es|en|s|e|i|o|a|n)$/, '') : w);

/**
 * Same food? Two items or names. When both are known foods: the same id, or one is the
 * other's `of` (farina 00 / farina). When both are known but different: never.
 * Otherwise the names themselves, plurals tolerated (uova / uovo).
 */
export function sameFood(a, b) {
  const x = foodOfItem(a); const y = foodOfItem(b);
  if (x && y) {
    if (x === y) return true;
    const fx = food(x); const fy = food(y);
    return fx?.of === y || fy?.of === x;
  }
  if (x || y) return false;
  const na = simple(typeof a === 'string' ? a : a?.name); const nb = simple(typeof b === 'string' ? b : b?.name);
  if (!na || !nb) return false;
  if (na === nb) return true;
  const wa = na.split(' '); const wb = nb.split(' ');
  if (wa.length !== wb.length) return false;
  return wa.every((w, i) => (i === wa.length - 1 ? stem(w) === stem(wb[i]) : w === wb[i]));
}

const FROZEN = /\b(?:surgelat\w*|congelat\w*|tiefkuhl\w*|tiefgekuhlt\w*|tk|frozen)\b/;
const CANNED = /\b(?:in scatola|in latta|canned|tinned|aus der dose|dose|konserve)\b/;
/** A name's department from the dictionary (frozen / canned wording first), or null when unknown. */
export function foodDept(nameOrItem) {
  const name = typeof nameOrItem === 'string' ? nameOrItem : nameOrItem?.name;
  const s = simple(name);
  const id = foodOfItem(nameOrItem);
  const d = id ? food(id).dept : null;
  if (d && NONFOOD_DEPTS.includes(d)) return d;
  if (FROZEN.test(s)) return 'frozen';
  if (d && CANNED.test(s) && (d === 'produce' || d === 'meatfish')) return 'staples';
  return d;
}

/**
 * The `food` / `foodPinned` fields for a new record (v40 contract): copied from a source that has them
 * (a recipe ingredient, a list item, a pantry product), else resolved from the name. {} when unknown.
 */
export function foodFields(name, from) {
  if (from && (from.food || from.foodPinned)) return { ...(from.food ? { food: from.food } : {}), ...(from.foodPinned ? { foodPinned: true } : {}) };
  const id = foodOf(name);
  return id ? { food: id } : {};
}

/**
 * After a rename: the record with `food` resolved again from the new name, unless a person pinned it.
 */
export function refood(rec, newName) {
  if (!rec || rec.foodPinned) return rec;
  const id = foodOf(newName);
  const out = { ...rec };
  if (id) out.food = id; else delete out.food;
  return out;
}

/** Every food, built-in and the user's own (records). */
export function allFoods() { return [...FOOD.values()]; }

/** Foods whose names contain the query (any language), best first: whole-name starts, then contains. */
export function searchFoods(q, lang = 'it', limit = 30) {
  const s = simple(q);
  if (!s) return [];
  const scored = [];
  for (const r of FOOD.values()) {
    const names = [r[lang], r.it, r.en, r.de, ...(r.alt || []), ...(r.userAlt || [])].filter(Boolean).map(simple);
    let score = 0;
    for (const n of names) {
      if (n === s) { score = 3; break; }
      if (n.startsWith(s)) score = Math.max(score, 2);
      else if (n.includes(s)) score = Math.max(score, 1);
    }
    if (score) scored.push([score, r]);
  }
  return scored.sort((a, b) => b[0] - a[0] || foodName(a[1].id, lang).localeCompare(foodName(b[1].id, lang))).slice(0, limit).map(([, r]) => r);
}

/** Counts as always at home (salt, pepper, oil, water, ice). */
export function isBasicFood(nameOrItem) {
  const id = foodOfItem(nameOrItem);
  return Boolean(id && food(id).basic);
}

/**
 * The user's own foods and extra names (data/foods.json, from Ricette v40).
 * Records: { id: 'u_…', it?, de?, en?, alt?, dept?, of? } for a new food, or { id: '<built-in id>', alt } for extra names.
 */
export function setUserFoods(list = []) {
  // drop earlier user foods, restore built-in records
  for (const [id, r] of [...FOOD]) if (r.user) FOOD.delete(id);
  for (const r of BUILTIN) { r.userAlt = undefined; }
  const extra = [];
  for (const u of list || []) {
    if (!u || !u.id || u.deleted) continue;
    const base = FOOD.get(u.id);
    if (base && !base.user) { base.userAlt = u.alt || []; extra.push({ id: u.id, alt: u.alt || [] }); continue; }
    const rec = { id: u.id, dept: u.dept || 'other', it: u.it || '', de: u.de || '', en: u.en || '', alt: u.alt || [], user: true, ...(u.of ? { of: u.of } : {}) };
    FOOD.set(u.id, rec);
    extra.push(rec);
  }
  rebuild(extra);
}

rebuild();
